fn main() {
    let n: u64 = std::env::args()
        .nth(1)
        .and_then(|s| s.trim().parse().ok())
        .unwrap_or(0);
    let mut a: Vec<u8> = vec![1];
    let mut b: Vec<u8> = vec![1];
    for _ in 1..n {
        let mut c: Vec<u8> = Vec::new();
        let mut carry: u8 = 0;
        let mut j = 0;
        while j < a.len().max(b.len()) || carry > 0 {
            let s = carry + a.get(j).copied().unwrap_or(0) + b.get(j).copied().unwrap_or(0);
            c.push(s % 10);
            carry = s / 10;
            j += 1;
        }
        a = b;
        b = c;
    }
    let s: String = b.iter().rev().map(|d| (d + 48) as char).collect();
    println!("{}", s);
